// ── Tilde expansion tests ──

#[test]
fn expand_tilde_leaves_non_tilde_paths_unchanged() {
    // Absolute paths without tilde should be unchanged
    assert_eq!(expand_tilde("/absolute/path"), "/absolute/path");
    assert_eq!(expand_tilde("/usr/local/bin"), "/usr/local/bin");

    // Relative paths without tilde should be unchanged
    assert_eq!(expand_tilde("relative/path"), "relative/path");
    assert_eq!(expand_tilde("./local"), "./local");
    assert_eq!(expand_tilde("../parent"), "../parent");

    // Empty string should remain empty
    assert_eq!(expand_tilde(""), "");
}

#[test]
fn expand_tilde_expands_tilde_slash_prefix() {
    // Set HOME for the test
    std::env::set_var("HOME", "/home/testuser");

    assert_eq!(expand_tilde("~/path"), "/home/testuser/path");
    assert_eq!(expand_tilde("~/Documents/file.txt"), "/home/testuser/Documents/file.txt");
    assert_eq!(expand_tilde("~/.config"), "/home/testuser/.config");
}

#[test]
fn expand_tilde_expands_bare_tilde() {
    // Set HOME for the test
    std::env::set_var("HOME", "/home/testuser");

    assert_eq!(expand_tilde("~"), "/home/testuser");
}

#[test]
fn expand_tilde_returns_path_unchanged_when_home_missing() {
    // Remove HOME environment variable
    std::env::remove_var("HOME");

    // When HOME is missing, tilde paths should be returned unchanged
    assert_eq!(expand_tilde("~/path"), "~/path");
    assert_eq!(expand_tilde("~"), "~");

    // Non-tilde paths should still be unchanged
    assert_eq!(expand_tilde("/absolute/path"), "/absolute/path");
    assert_eq!(expand_tilde("relative/path"), "relative/path");
}

#[test]
fn expand_tilde_handles_complex_paths() {
    // Set HOME for the test
    std::env::set_var("HOME", "/home/testuser");

    // Paths with multiple components
    assert_eq!(
        expand_tilde("~/deeply/nested/path/to/file.txt"),
        "/home/testuser/deeply/nested/path/to/file.txt"
    );

    // Paths with special characters (should work fine)
    assert_eq!(expand_tilde("~/path with spaces"), "/home/testuser/path with spaces");
}

